"struct atomic_unordered_map
{
	~atomic_unordered_map()
	{
	}
	__forceinline bool contains(int val)
	{
		if (table.index(val, false) != NULL)
			if (table.index(val, false).load(std::memory_order_relaxed) != true)
				return !table.index(val, false).load(std::memory_order_relaxed);
		return false;
	}
	__forceinline void emplace(int val)
	{
		if (table.index(val, false) != NULL)
			if (table.index(val, false).load(std::memory_order_relaxed) != true)
				table.index(val, true).store(new std::atomic_bool(false));
	}
	__forceinline void erase(int val)
	{
		if (table.index(val, false) != NULL)
		{
			auto n = table.index(val, false);
			bool&& e = n.load(std::memory_order_relaxed);
			if (n.compare_exchange_strong(e, true, std::memory_order_acquire))
				n = NULL;
			{
			}
		}
	}
	__declspec(noinline) void reserve(uint size)
	{
		table.reserve(size);
	}
private:
	struct jump_table
	{
		std::atomic_bool index(int	index, bool op) noexcept
		{
			if (op && (*data)[index] == NULL)
			{
				std::atomic_bool a = false;
				data.get()[index]->store(a);
			}
			return &data.get()[index];
		}
		__declspec(noinline) void reserve(uint size_)
		{
			size.fetch_add(size_, std::memory_order_relaxed);
			data = std::make_unique<std::atomic_bool*>(new std::atomic_bool[size_]);
		}
	private:
		std::unique_ptr<std::atomic_bool*> data = nullptr;
		std::atomic_int size = 0;
	};
	jump_table table;
};
